// Parsear comprovante de assinatura do Zaping
// Formato: "Comprovante de assinatura NOME - TIPO assinou o documento NOME - CONTRATO - TIPO.pdf"
const items = $input.all();
const results = [];

for (const item of items) {
  const subject = (item.json.subject || '').trim();
  const body = (item.json.text || item.json.snippet || '').trim();
  const fullText = subject + ' ' + body;
  const messageId = item.json.id || item.json.messageId || '';

  // --- EXTRAIR NOME DO CLIENTE ---
  let nome_cliente = '';
  // Tenta: "Comprovante de assinatura NOME - TIPO"
  const compMatch = fullText.match(/[Cc]omprovante de assinatura\s+([A-Z\u00C0-\u017F\s]+?)\s*-\s*/i);
  if (compMatch) {
    nome_cliente = compMatch[1].trim();
  }
  // Fallback: "NOME assinou o documento"
  if (!nome_cliente) {
    const assMatch = fullText.match(/([A-Z\u00C0-\u017F][A-Z\u00C0-\u017F\s]+?)\s+assinou/i);
    if (assMatch) nome_cliente = assMatch[1].trim();
  }

  // --- EXTRAIR NOME DO DOCUMENTO ---
  let doc_nome = '';
  const docMatch = fullText.match(/assinou o documento\s+(.+?\.pdf)/i);
  if (docMatch) {
    doc_nome = docMatch[1].trim();
  }

  // --- EXTRAIR TIPO DE PROCESSO ---
  let tipo_processo = 'FIES_ESF'; // default
  const tipoMap = {
    'desenrola fies': 'FIES_ESF',
    'fies esf': 'FIES_ESF',
    'fies dgm': 'FIES_DGM',
    'covid': 'COVID',
    'mais medicos': 'MAIS_MEDICOS',
    'mais m\u00e9dicos': 'MAIS_MEDICOS',
    'residencia': 'RESIDENCIA',
    'resid\u00eancia': 'RESIDENCIA',
    'cfm': 'CFM_CRM',
    'crm': 'CFM_CRM'
  };
  const textLower = fullText.toLowerCase();
  for (const [key, val] of Object.entries(tipoMap)) {
    if (textLower.includes(key)) {
      tipo_processo = val;
      break;
    }
  }

  // --- EXTRAIR CPF/CNPJ (se presente no body) ---
  const cpfMatch = fullText.match(/(\d{3}\.?\d{3}\.?\d{3}-?\d{2})|(\d{2}\.?\d{3}\.?\d{3}\/?\d{4}-?\d{2})/);
  const cpf_cnpj = cpfMatch ? cpfMatch[0].replace(/[^\d]/g, '') : '';

  // --- EXTRAIR EMAIL ---
  const emailMatch = fullText.match(/(?:e-?mail)[:\s]*([\w.+-]+@[\w.-]+\.[a-z]{2,})/i);
  const email = emailMatch ? emailMatch[1] : '';

  // --- EXTRAIR TELEFONE ---
  const phoneMatch = fullText.match(/(?:tel|telefone|fone|whatsapp|celular)[:\s]*(\(?\d{2}\)?\s?\d{4,5}-?\d{4})/i);
  const telefone = phoneMatch ? phoneMatch[1].replace(/[^\d]/g, '') : '';

  // --- VERIFICAR SE TEM ANEXO ---
  const payload = item.json.payload || {};
  const parts = payload.parts || [];
  let tem_anexo = false;
  let attachment_id = '';
  let attachment_filename = '';
  let attachment_mime = '';

  function findAttachment(partsList) {
    for (const part of partsList) {
      if (part.filename && part.filename.length > 0 && part.body && part.body.attachmentId) {
        tem_anexo = true;
        attachment_id = part.body.attachmentId;
        attachment_filename = part.filename;
        attachment_mime = part.mimeType || 'application/pdf';
        return;
      }
      if (part.parts) findAttachment(part.parts);
    }
  }
  findAttachment(parts);

  // Tambem checar binary data do n8n
  if (!tem_anexo && item.binary) {
    const binKeys = Object.keys(item.binary);
    if (binKeys.length > 0) {
      tem_anexo = true;
      attachment_filename = item.binary[binKeys[0]].fileName || doc_nome || 'documento.pdf';
      attachment_mime = item.binary[binKeys[0]].mimeType || 'application/pdf';
    }
  }

  results.push({
    json: {
      nome_cliente,
      cpf_cnpj,
      email,
      telefone,
      tipo_processo,
      doc_nome,
      tem_anexo,
      attachment_id,
      attachment_filename,
      attachment_mime,
      message_id: messageId,
      email_subject: subject,
      raw_body: body
    }
  });
}

return results;

// Unificar dados: pegar dados parseados + possivel anexo do Get Message
const emailData = $('Extrair Dados do Email').item.json;
let binary = null;
let attachment_filename = emailData.attachment_filename || emailData.doc_nome || 'documento.pdf';

// Checar se veio binary do Gmail Trigger ou do Get Message
try {
  const triggerItem = $('Gmail Trigger').item;
  if (triggerItem.binary && Object.keys(triggerItem.binary).length > 0) {
    binary = triggerItem.binary;
    const key = Object.keys(binary)[0];
    attachment_filename = binary[key].fileName || attachment_filename;
  }
} catch(e) {}

try {
  const getMessage = $('Buscar Email Completo').item;
  if (getMessage.binary && Object.keys(getMessage.binary).length > 0) {
    binary = getMessage.binary;
    const key = Object.keys(binary)[0];
    attachment_filename = binary[key].fileName || attachment_filename;
  }
} catch(e) {}

const result = {
  json: {
    ...emailData,
    attachment_filename,
    has_binary: binary !== null
  }
};

if (binary) result.binary = binary;

return [result];

// Extrair dados do cliente a partir do texto do PDF
const emailData = $('Unificar Dados + Anexo').item.json;
const pdfText = $input.item.json.data || $input.item.json.text || "";

// --- CPF/CNPJ ---
let cpf_cnpj = emailData.cpf_cnpj || "";
if (!cpf_cnpj) {
  const cpfFmt = pdfText.match(/\d{3}\.\d{3}\.\d{3}-\d{2}/);
  if (cpfFmt) {
    cpf_cnpj = cpfFmt[0].replace(/[^\d]/g, "");
  }
}
if (!cpf_cnpj) {
  const cnpjFmt = pdfText.match(/\d{2}\.\d{3}\.\d{3}\/\d{4}-\d{2}/);
  if (cnpjFmt) {
    cpf_cnpj = cnpjFmt[0].replace(/[^\d]/g, "");
  }
}
if (!cpf_cnpj) {
  const seqs = pdfText.match(/\b\d{11}\b/g) || [];
  for (const seq of seqs) {
    if (!/^(\d)\1{10}$/.test(seq)) {
      cpf_cnpj = seq;
      break;
    }
  }
}

// --- TELEFONE ---
let telefone = emailData.telefone || "";
if (!telefone) {
  const phonePatterns = [
    /\(?\d{2}\)?\s?9\d{4}[-.\s]?\d{4}/,
    /\(?\d{2}\)?\s?\d{4}[-.\s]?\d{4}/,
    /\b\d{2}\s?9\d{8}\b/,
    /\b\d{2}\s?\d{8}\b/
  ];
  for (const pattern of phonePatterns) {
    const phoneMatch = pdfText.match(pattern);
    if (phoneMatch) {
      telefone = phoneMatch[0].replace(/[^\d]/g, "");
      if (telefone.length >= 10 && telefone.length <= 11) break;
      telefone = "";
    }
  }
}

// --- NOME (fallback) ---
let nome_cliente = emailData.nome_cliente || "";
if (!nome_cliente) {
  const nomePatterns = [
    /(?:nome|cliente|contratante|assinante|outorgante)[:\s]+([A-Z\u00C0-\u017F][A-Z\u00C0-\u017Fa-z\u00e0-\u00ff\s]{3,50})/i,
    /(?:eu,?\s+)([A-Z\u00C0-\u017F][A-Z\u00C0-\u017Fa-z\u00e0-\u00ff\s]{3,50})(?:,|\s+portador)/i
  ];
  for (const pattern of nomePatterns) {
    const nomeMatch = pdfText.match(pattern);
    if (nomeMatch) {
      nome_cliente = nomeMatch[1].trim();
      break;
    }
  }
}

// NAO extrai email do PDF - o email que aparece no contrato e do advogado, nao do cliente

const result = {
  json: {
    ...emailData,
    cpf_cnpj,
    telefone,
    nome_cliente,
    dados_extraidos_do_pdf: true,
    pdf_text_preview: pdfText.substring(0, 500)
  }
};

try {
  const unified = $('Unificar Dados + Anexo').item;
  if (unified.binary) result.binary = unified.binary;
} catch(e) {}

return [result];

// Montar o payload para o endpoint do app (find-or-create + procuracao assinada).
// Le os dados extraidos (email/PDF) + o resultado do upload ao Drive (nó anterior).
// Usa try/catch para tolerar o branch em que 'Extrair Dados do PDF' NAO executou
// (CPF ja veio do email), evitando erro de 'referenced node unexecuted'.

const uploaded = $input.item.json; // saida do 'Upload Documento' (Google Drive)

const unified = $('Unificar Dados + Anexo').item.json;

let pdf = {};
try {
  pdf = $('Extrair Dados do PDF').item.json || {};
} catch (e) {
  pdf = {};
}

const nome_cliente = pdf.nome_cliente || unified.nome_cliente || '';
const cpf_cnpj = (pdf.cpf_cnpj || unified.cpf_cnpj || '').replace(/[^\d]/g, '');
const email = unified.email || null;
const telefone = unified.telefone || pdf.telefone || null;
const tipo_processo = unified.tipo_processo; // slug ja mapeado (FIES_ESF etc.)
const municipio = unified.municipio || null;

const payload = {
  nome_cliente,
  cpf_cnpj,
  email,
  telefone,
  tipo_processo,
  municipio,
  responsavel: null,
  proximo_passo: null,
  assinado: true,
  documento_assinado: {
    drive_file_id: uploaded.id || null,
    drive_url: uploaded.webViewLink || null,
    name: 'Procuração',
    zapsign_doc_token: null
  }
};

return [{ json: { payload } }];
